const encoder = new TextEncoder();

it("keeps preview runtime installation, pruning and invalidation outside the stock cache", () => {
  for (const script of [
    buildWslRuntimeInstallScript("/tmp/runtime.tar.gz", "sha256-preview", "a".repeat(64), true),
