// @effect-diagnostics nodeBuiltinImport:off
import * as NodeChildProcess from "node:child_process";
import * as NodeFS from "node:fs";
import * as NodeOS from "node:os";
import * as NodePath from "node:path";
import { afterEach, describe, expect, it } from "vite-plus/test";

import {
  buildCopilotExecutableReadinessScript,
  copilotLinuxExecutableMembers,
  validateCopilotLinuxArchiveMembers,
} from "./copilotRuntime.ts";

const roots: string[] = [];
afterEach(() => {
  for (const root of roots.splice(0)) NodeFS.rmSync(root, { recursive: true, force: true });
});
const uname = NodeChildProcess.spawnSync("uname", ["-m"], { encoding: "utf8" });
const arch = ["arm64", "aarch64"].includes(uname.stdout?.trim()) ? "arm64" : "x64";

function fixture(withCopilot = true) {
  const root = NodeFS.mkdtempSync(NodePath.join(NodeOS.tmpdir(), "t3-copilot-modes-"));
  roots.push(root);
  const write = (relative: string, source = "{}") => {
    const file = NodePath.join(root, relative);
    NodeFS.mkdirSync(NodePath.dirname(file), { recursive: true });
    NodeFS.writeFileSync(file, source, { mode: 0o644 });
    return file;
  };
  if (withCopilot) {
    for (const name of ["copilot", "copilot-sdk", `copilot-linux-${arch}`]) {
      write(`node_modules/@github/${name}/package.json`);
    }
    for (const [index, relative] of copilotLinuxExecutableMembers(arch).entries()) {
      write(relative, `#!/bin/sh\nprintf '${["copilot", "rg", "tgrep"][index]}\\n'\n`);
    }
  }
  const run = (action: string) =>
    NodeChildProcess.spawnSync(
      "bash",
      [
        "-c",
        `set -eu\n${buildCopilotExecutableReadinessScript()}\n${action}`,
        "readiness-test",
        root,
      ],
      { encoding: "utf8" },
    );
  return { root, write, run };
}

describe("Copilot Linux archive members", () => {
  const archiveMembers = (arch: "x64" | "arm64") => [
    ...["copilot", "copilot-sdk", `copilot-linux-${arch}`].map(
      (name) => `node_modules/@github/${name}/package.json`,
    ),
    ...copilotLinuxExecutableMembers(arch),
  ];
  it.each(["x64", "arm64"] as const)("accepts a complete %s payload", (arch) => {
    const members = archiveMembers(arch);
    expect(validateCopilotLinuxArchiveMembers(members, arch)).toBeNull();
    expect(validateCopilotLinuxArchiveMembers([], arch)).toBeNull();
  });
  it.each(["x64", "arm64"] as const)(
    "rejects missing, duplicate, wrong-platform and non-target %s commands",
    (arch) => {
      const members = archiveMembers(arch);
      for (const broken of [
        members.slice(1),
        members.slice(0, -1),
        [...members, members.at(-1)!],
        [...members, "node_modules/@github/copilot-win32-x64/copilot.exe"],
        [...members, `node_modules/@github/copilot-linux-${arch}/ripgrep/bin/linux-wrong/rg`],
      ])
        expect(validateCopilotLinuxArchiveMembers(broken, arch)).not.toBeNull();
    },
  );
});

describe.skipIf(uname.status !== 0 || NodeOS.type() === "Windows_NT")(
  "production Copilot mode functions (executed)",
  () => {
    it("normalizes all three commands and preserves explicit newline fixture output", () => {
      const stage = fixture();
      expect(stage.run('copilot_executable_payload_ready "$1"').status).not.toBe(0);
      const result = stage.run(
        'normalize_copilot_executable_modes "$1"\n"$copilot_package_dir/copilot"\n"$copilot_package_dir/ripgrep/bin/$copilot_target/rg"\n"$copilot_package_dir/tgrep/bin/$copilot_target/tgrep"',
      );
      expect(result.status, result.stderr).toBe(0);
      expect(result.stdout).toBe("copilot\nrg\ntgrep\n");
      for (const file of copilotLinuxExecutableMembers(arch)) {
        expect(NodeFS.statSync(NodePath.join(stage.root, file)).mode & 0o777).toBe(0o755);
      }
      NodeFS.chmodSync(NodePath.join(stage.root, copilotLinuxExecutableMembers(arch)[1]!), 0o644);
      expect(stage.run('copilot_executable_payload_ready "$1"').status).not.toBe(0);
      expect(stage.run('normalize_copilot_executable_modes "$1"').status).toBe(0);
    });

    it("checks the complete layout before chmod and rejects ambiguous targets", () => {
      const stage = fixture();
      NodeFS.rmSync(NodePath.join(stage.root, copilotLinuxExecutableMembers(arch)[2]!));
      expect(stage.run('normalize_copilot_executable_modes "$1"').status).not.toBe(0);
      expect(
        NodeFS.statSync(NodePath.join(stage.root, copilotLinuxExecutableMembers(arch)[0]!)).mode &
          0o777,
      ).toBe(0o644);
      stage.write(copilotLinuxExecutableMembers(arch)[2]!);
      stage.write(
        `node_modules/@github/copilot-linux-${arch === "x64" ? "arm64" : "x64"}/package.json`,
      );
      expect(stage.run('normalize_copilot_executable_modes "$1"').status).not.toBe(0);
    });

    it("does not follow a command symlink or silently accept a missing SDK", () => {
      const stage = fixture();
      const executable = NodePath.join(stage.root, copilotLinuxExecutableMembers(arch)[0]!);
      const target = stage.write("outside-command", "#!/bin/sh\nexit 0\n");
      NodeFS.rmSync(executable);
      NodeFS.symlinkSync(target, executable);
      expect(stage.run('normalize_copilot_executable_modes "$1"').status).not.toBe(0);
      expect(NodeFS.statSync(target).mode & 0o777).toBe(0o644);
      NodeFS.rmSync(executable);
      stage.write(copilotLinuxExecutableMembers(arch)[0]!);
      NodeFS.rmSync(NodePath.join(stage.root, "node_modules/@github/copilot-sdk"), {
        recursive: true,
      });
      expect(stage.run('normalize_copilot_executable_modes "$1"').status).not.toBe(0);
    });

    it("leaves non-Copilot runtimes unchanged", () => {
      const stage = fixture(false);
      const before = NodeFS.readdirSync(stage.root);
      expect(
        stage.run('normalize_copilot_executable_modes "$1"\ncopilot_executable_payload_ready "$1"')
          .status,
      ).toBe(0);
      expect(NodeFS.readdirSync(stage.root)).toEqual(before);
    });
  },
);

export function copilotLinuxExecutableMembers(arch: "x64" | "arm64"): ReadonlyArray<string> {
  const root = `node_modules/@github/copilot-linux-${arch}`;
  return [
    `${root}/copilot`,
    `${root}/ripgrep/bin/linux-${arch}/rg`,
    `${root}/tgrep/bin/linux-${arch}/tgrep`,
  ];
}

/** Members are relative to the single top-level Linux CLI archive directory. */
export function validateCopilotLinuxArchiveMembers(
  members: ReadonlyArray<string>,
  arch: "x64" | "arm64",
): string | null {
  const prefix = "node_modules/@github/";
  const packages = new Set(
    members.flatMap((member) => {
      if (!member.startsWith(prefix)) return [];
      const name = member.slice(prefix.length).split("/")[0]!;
      return name === "copilot" || name.startsWith("copilot-") ? [name] : [];
    }),
  );
  if (packages.size === 0) return null;
  const expected = new Set(["copilot", "copilot-sdk", `copilot-linux-${arch}`]);
  if (packages.size !== expected.size || [...packages].some((name) => !expected.has(name))) {
    return "Copilot archive must contain its SDK, runtime and exactly one matching Linux platform package.";
  }
  const required = [
    ...[...expected].map((name) => `${prefix}${name}/package.json`),
    ...copilotLinuxExecutableMembers(arch),
  ];
  if (required.some((file) => members.filter((member) => member === file).length !== 1)) {
    return "Copilot archive has missing or duplicate runtime manifests or commands.";
  }
  const platformRoot = `${prefix}copilot-linux-${arch}/`;
  const commands = members.filter(
    (member) =>
      member.startsWith(platformRoot) &&
      /\/(?:copilot(?:\.exe)?|(?:ripgrep|tgrep)\/bin\/[^/]+\/(?:rg|tgrep)(?:\.exe)?)$/.test(member),
  );
  const expectedCommands = new Set(copilotLinuxExecutableMembers(arch));
  if (commands.length !== 3 || commands.some((member) => !expectedCommands.has(member))) {
    return "Copilot archive contains unexpected platform commands.";
  }
  return null;
}

/** The same POSIX checks are used before cache promotion and on every warm reuse. */
export function buildCopilotExecutableReadinessScript(): string {
  return [
    "copilot_payload_present() {",
    '  for candidate in "$1/node_modules/@github/copilot" "$1"/node_modules/@github/copilot-*; do',
    '    if [ -e "$candidate" ] || [ -L "$candidate" ]; then return 0; fi',
    "  done",
    "  return 1",
    "}",
    "copilot_payload_layout() {",
    '  [ -d "$1/node_modules" ] && [ ! -L "$1/node_modules" ] || return 1',
    '  [ -d "$1/node_modules/@github" ] && [ ! -L "$1/node_modules/@github" ] || return 1',
    '  for candidate in "$1/node_modules/@github/copilot" "$1/node_modules/@github/copilot-sdk"; do',
    '    [ -d "$candidate" ] && [ ! -L "$candidate" ] && [ -f "$candidate/package.json" ] && [ ! -L "$candidate/package.json" ] || return 1',
    "  done",
    "  copilot_package_count=0",
    '  for candidate in "$1"/node_modules/@github/copilot-*; do',
    '    [ -e "$candidate" ] || [ -L "$candidate" ] || continue',
    '    case "$candidate" in',
    "      */copilot-sdk) continue ;;",
    "      */copilot-linux-x64) copilot_target=linux-x64 ;;",
    "      */copilot-linux-arm64) copilot_target=linux-arm64 ;;",
    "      *) return 1 ;;",
    "    esac",
    '    [ -d "$candidate" ] && [ ! -L "$candidate" ] || return 1',
    '    copilot_package_dir="$candidate"',
    "    copilot_package_count=$((copilot_package_count + 1))",
    "  done",
    '  [ "$copilot_package_count" -eq 1 ] || return 1',
    '  case "$(uname -m)" in',
    '    x86_64|amd64) [ "$copilot_target" = linux-x64 ] || return 1 ;;',
    '    aarch64|arm64) [ "$copilot_target" = linux-arm64 ] || return 1 ;;',
    "    *) return 1 ;;",
    "  esac",
    '  [ -f "$copilot_package_dir/package.json" ] && [ ! -L "$copilot_package_dir/package.json" ] || return 1',
    '  for directory in "$copilot_package_dir/ripgrep" "$copilot_package_dir/ripgrep/bin" "$copilot_package_dir/ripgrep/bin/$copilot_target" "$copilot_package_dir/tgrep" "$copilot_package_dir/tgrep/bin" "$copilot_package_dir/tgrep/bin/$copilot_target"; do',
    '    [ -d "$directory" ] && [ ! -L "$directory" ] || return 1',
    "  done",
    '  for command_dir in "$copilot_package_dir"/ripgrep/bin/* "$copilot_package_dir"/tgrep/bin/*; do',
    '    [ "${command_dir##*/}" = "$copilot_target" ] || return 1',
    "  done",
    '  for executable in "$copilot_package_dir/copilot" "$copilot_package_dir/ripgrep/bin/$copilot_target/rg" "$copilot_package_dir/tgrep/bin/$copilot_target/tgrep"; do',
    '    [ -f "$executable" ] && [ ! -L "$executable" ] || return 1',
    "  done",
    "}",
    "copilot_executable_payload_ready() {",
    '  copilot_payload_present "$1" || return 0',
    '  if ! copilot_payload_layout "$1"; then',
    "    printf 'Linux Copilot payload has a missing, ambiguous, or incompatible layout\\n' >&2",
    "    return 1",
    "  fi",
    '  for executable in "$copilot_package_dir/copilot" "$copilot_package_dir/ripgrep/bin/$copilot_target/rg" "$copilot_package_dir/tgrep/bin/$copilot_target/tgrep"; do',
    '    if [ ! -x "$executable" ]; then',
    "      printf 'Linux Copilot command is not executable: %s\\n' \"$executable\" >&2",
    "      return 1",
    "    fi",
    "  done",
    "}",
    "normalize_copilot_executable_modes() {",
    '  copilot_payload_present "$1" || return 0',
    '  if ! copilot_payload_layout "$1"; then',
    "    printf 'Linux Copilot payload has a missing, ambiguous, or incompatible layout\\n' >&2",
    "    return 1",
    "  fi",
    '  for executable in "$copilot_package_dir/copilot" "$copilot_package_dir/ripgrep/bin/$copilot_target/rg" "$copilot_package_dir/tgrep/bin/$copilot_target/tgrep"; do',
    '    if ! chmod 0755 "$executable"; then',
    "      printf 'Could not make Linux Copilot command executable: %s\\n' \"$executable\" >&2",
    "      return 1",
    "    fi",
    "  done",
    '  copilot_executable_payload_ready "$1"',
    "}",
  ].join("\n");
}

