  const env: Record<string, string> = {};
  if (options.root)
    env.T3CODE_FORK_PREVIEW_HOME =
      options.root === "live" ? NodePath.join(home, ".t3") : options.root;
  if (options.existingHome)
    env.T3CODE_HOME =
      options.existingHome === "preview"
        ? NodePath.join(home, ".t3-fork-preview")
        : options.existingHome;
  if (options.inheritedPreview) env.T3CODE_DESKTOP_ISOLATED_PREVIEW = "true";
  let loaded = false;
  let quit = false;
  let profile = "";
  let compileCache = "";
  try {
    NodeVM.runInNewContext(bootstrap, {
      process: { env },
      require: (name: string) => {
        if (name === "node:fs") return NodeFS;
        if (name === "node:os") return { homedir: () => home };
        if (name === "node:path") return NodePath;
        if (name === "node:module")
          return {
            constants: { compileCacheStatus: { FAILED: 0 } },
            enableCompileCache: (directory: string) => {
              compileCache = directory;
              return { status: options.cacheFailure ? 0 : 1, directory };
            },
          };
        if (name === "electron")
          return {
            app: {
              setPath: (_key: string, value: string) => {
                profile = value;
              },
              requestSingleInstanceLock: () => options.primary !== false,
              quit: () => {
                quit = true;
              },
            },
          };
        if (name === "./apps/desktop/dist-electron/boot.cjs") {
          expect(profile).toBe(NodePath.join(env.T3CODE_HOME!, "electron"));
          expect(env.T3CODE_DISABLE_AUTO_UPDATE).toBe("true");
          expect(compileCache).toBe(NodePath.join(env.T3CODE_HOME!, "compile-cache"));
          loaded = true;
          return {};
        }
        throw new Error(`Unexpected module ${name}`);
      },
    });
    return { home, profile, env, loaded, quit };
  } finally {
    NodeFS.rmSync(home, { recursive: true });
  }
}

describe("fork preview packaging isolation", () => {
  it("removes update feeds and stock protocol claims without mutating ordinary configuration", () => {
    const original = {
      appId: "com.t3tools.t3code",
      publish: [{ provider: "github" }],
      protocols: [{ schemes: ["t3code"] }],
      mac: { protocols: [{ schemes: ["t3code"] }], icon: "icon.icns" },
    };
    const result = forkPreviewBuildConfig(original);
    expect(result.appId).toBe(FORK_PREVIEW_APP_ID);
    expect(result.publish).toBeNull();
    expect(result).not.toHaveProperty("protocols");
    expect(result.mac).toEqual({ protocols: [], icon: "icon.icns" });
    expect(original.publish).toHaveLength(1);
    expect(original.mac.protocols).toHaveLength(1);
  });
  it("sets isolated server and Electron homes before booting the app", () => {
    const result = runBootstrap();
    expect(result.env.T3CODE_HOME).toBe(NodePath.join(result.home, ".t3-fork-preview"));
    expect(result.profile).not.toContain(NodePath.join("Application Support", "t3code"));
    expect(result.loaded).toBe(true);
    expect(result.quit).toBe(false);
  });
  it("refuses the live profile and prevents a secondary process from booting another backend", () => {
    expect(() => runBootstrap({ root: "live" })).toThrow("ordinary T3 profile");
    expect(runBootstrap({ primary: false })).toMatchObject({ loaded: false, quit: true });
    expect(runBootstrap({ inheritedPreview: true, existingHome: "preview" }).loaded).toBe(true);
    expect(() => runBootstrap({ cacheFailure: true })).toThrow("isolated compile cache");
  });
});

export const FORK_PREVIEW_APP_ID = "com.tesseracode.t3code.preview";
export const FORK_PREVIEW_PRODUCT_NAME = "T3 Code Fork Preview";

/** Installer identity and update metadata are isolated before electron-builder sees the stage. */
export function forkPreviewBuildConfig(config: Record<string, unknown>): Record<string, unknown> {
  const { publish: _publish, protocols: _protocols, ...rest } = config;
  return {
    ...rest,
    publish: null,
    appId: FORK_PREVIEW_APP_ID,
    productName: FORK_PREVIEW_PRODUCT_NAME,
    artifactName: "T3-Code-Fork-Preview-${version}-${arch}.${ext}",
    ...(typeof config.mac === "object" && config.mac !== null
      ? { mac: { ...config.mac, protocols: [] } }
      : {}),
    ...(typeof config.dmg === "object" && config.dmg !== null
      ? { dmg: { ...config.dmg, title: FORK_PREVIEW_PRODUCT_NAME } }
      : {}),
  };
}

import * as NodeServices from "@effect/platform-node/NodeServices";
import { assert, it } from "@effect/vitest";
import * as Effect from "effect/Effect";
import * as FileSystem from "effect/FileSystem";
import * as Path from "effect/Path";
import {
  collectCliRuntimeExternalDependencies,
  RuntimeExternalDependencyError,
} from "./runtime-external-dependencies.ts";

const fixture = Effect.fn("test.runtimeOwners")(function* (conflict = false, missing = false) {
  const fs = yield* FileSystem.FileSystem;
  const path = yield* Path.Path;
  const root = yield* fs.makeTempDirectoryScoped({ prefix: "t3-runtime-owners-" });
  yield* fs.writeFileString(
    path.join(root, "pnpm-workspace.yaml"),
    'packages: ["apps/*", "packages/*"]\ncatalog:\n  node-pty: 1.2.0-beta.15\n',
  );
  for (const [directory, manifest] of Object.entries({
    "apps/server": { name: "t3", dependencies: { "@test/provider": "workspace:*" } },
    "packages/provider": {
      name: "@test/provider",
      dependencies: {
        "@test/helper": "workspace:*",
        "node-pty": "catalog:",
        effect: "4.0.5",
      },
    },
    "packages/helper": {
      name: "@test/helper",
      dependencies: {
        "@test/provider": "workspace:*",
        ...(missing ? { "@test/missing": "workspace:*" } : {}),
        ...(conflict ? { "node-pty": "different" } : { "playwright-core": "1.58.2" }),
      },
    },
    "packages/unreachable": { name: "@test/unreachable", dependencies: { "node-pty": "wrong" } },
  })) {
    yield* fs.makeDirectory(path.join(root, directory), { recursive: true });
    yield* fs.writeFileString(path.join(root, directory, "package.json"), JSON.stringify(manifest));
  }
  return root;
});

it.layer(NodeServices.layer)("workspace-owned runtime externals", (it) => {
  it.effect(
    "stages the reachable owner closure, resolving catalogs and cycles without unrelated packages",
    () =>
      Effect.gen(function* () {
        const root = yield* fixture();
        assert.deepStrictEqual(yield* collectCliRuntimeExternalDependencies(root), {
          "node-pty": "1.2.0-beta.15",
          "playwright-core": "1.58.2",
        });
      }),
  );
  it.effect.each([
    [true, false],
    [false, true],
  ] as const)(
    "refuses incompatible flattened owners or missing workspace edges (%s, %s)",
    ([conflict, missing]) =>
      Effect.gen(function* () {
        const root = yield* fixture(conflict, missing);
        const error = yield* collectCliRuntimeExternalDependencies(root).pipe(Effect.flip);
        assert.instanceOf(error, RuntimeExternalDependencyError);
        assert.include(
          error.detail,
          conflict ? "Cannot flatten node-pty" : "missing workspace owner",
        );
      }),
  );
});

// @effect-diagnostics nodeBuiltinImport:off
import * as NodeFS from "node:fs";
import * as Effect from "effect/Effect";
import * as FileSystem from "effect/FileSystem";
import * as Path from "effect/Path";
import * as Schema from "effect/Schema";
import { fromYaml } from "@t3tools/shared/schemaYaml";
import { selectCliRuntimeExternalDependencies } from "./cli-external-packages.ts";
import { resolveCatalogDependencies } from "./resolve-catalog.ts";

const Workspace = Schema.Struct({
  packages: Schema.Array(Schema.String),
  catalog: Schema.optional(Schema.Record(Schema.String, Schema.String)),
});
const Manifest = Schema.Struct({
  name: Schema.String,
  dependencies: Schema.optional(Schema.Record(Schema.String, Schema.String)),
  optionalDependencies: Schema.optional(Schema.Record(Schema.String, Schema.String)),
});
const decodeManifest = Schema.decodeEffect(Schema.fromJsonString(Manifest));

export class RuntimeExternalDependencyError extends Schema.TaggedError<RuntimeExternalDependencyError>()(
  "RuntimeExternalDependencyError",
  { detail: Schema.String, cause: Schema.optional(Schema.Defect()) },
) {}

/** Follow workspace owners because provider dependencies no longer live in the server manifest. */
export const collectCliRuntimeExternalDependencies = Effect.fn(
  "collectCliRuntimeExternalDependencies",
)(function* (repoRoot: string) {
  const fs = yield* FileSystem.FileSystem;
  const path = yield* Path.Path;
  const workspace = yield* Schema.decodeEffect(fromYaml(Workspace))(
    yield* fs.readFileString(path.join(repoRoot, "pnpm-workspace.yaml")),
  );
  const manifestPaths = yield* Effect.try({
    try: () =>
      NodeFS.globSync(
        workspace.packages.map((pattern) => `${pattern}/package.json`),
        { cwd: repoRoot },
      ),
    catch: (cause) =>
      new RuntimeExternalDependencyError({
        detail: "Could not enumerate workspace owners.",
        cause,
      }),
  });
  const owners = new Map<string, { manifest: typeof Manifest.Type; file: string }>();
  for (const file of manifestPaths.sort()) {
    const manifest = yield* decodeManifest(yield* fs.readFileString(path.join(repoRoot, file)));
    if (owners.has(manifest.name)) {
      return yield* new RuntimeExternalDependencyError({
        detail: `Duplicate workspace owner ${manifest.name}.`,
      });
    }
    owners.set(manifest.name, { manifest, file });
  }
  const serverFile = "apps/server/package.json";
  const server = yield* decodeManifest(yield* fs.readFileString(path.join(repoRoot, serverFile)));
  const queue = [{ manifest: server, file: serverFile }];
  const visited = new Set<string>();
  const dependencies: Record<string, string> = {};
  const selectedOwners = new Map<string, string>();
  for (const owner of queue) {
    if (visited.has(owner.manifest.name)) continue;
    visited.add(owner.manifest.name);
    const declared = {
      ...owner.manifest.dependencies,
      ...owner.manifest.optionalDependencies,
    };
    for (const [name, spec] of Object.entries(declared)) {
      if (!spec.startsWith("workspace:")) continue;
      const child = owners.get(name);
      if (!child) {
        return yield* new RuntimeExternalDependencyError({
          detail: `${owner.file} requires missing workspace owner ${name}.`,
        });
      }
      queue.push(child);
    }
    const resolved = resolveCatalogDependencies(declared, workspace.catalog ?? {}, owner.file);
    for (const [name, version] of Object.entries(selectCliRuntimeExternalDependencies(resolved))) {
      if (version.startsWith("workspace:")) continue;
      if (dependencies[name] !== undefined && dependencies[name] !== version) {
        return yield* new RuntimeExternalDependencyError({
          detail: `Cannot flatten ${name}: ${selectedOwners.get(name)} requires ${dependencies[name]}, but ${owner.file} requires ${version}.`,
        });
      }
      dependencies[name] = version;
      selectedOwners.set(name, owner.file);
    }
  }
  return dependencies;
});
